// Manifest checks for store submission: node --test test/*.test.js
//
// addons.mozilla.org refuses new extensions without a data-collection
// declaration, and every icon the manifest names must exist at its declared
// size (they're generated by tools/make_icons.py).
const test = require("node:test");
const assert = require("node:assert");
const fs = require("fs");
const path = require("path");

const extDir = path.join(__dirname, "../extension");
const manifest = JSON.parse(fs.readFileSync(path.join(extDir, "manifest.json"), "utf8"));

/**
 * Reads a PNG's width and height from its IHDR chunk.
 *
 * @param {string} file  Path to a PNG.
 * @returns {{width: number, height: number}}
 * @throws {Error} if the file isn't a PNG.
 */
function pngSize(file) {
  const buf = fs.readFileSync(file);
  if (buf.toString("latin1", 1, 4) !== "PNG") throw new Error(`${file} is not a PNG`);
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

test("declares data collection (required for new AMO submissions)", () => {
  assert.deepStrictEqual(manifest.browser_specific_settings.gecko.data_collection_permissions, { required: ["none"] });
});

test("has a fixed add-on id (saved logins are stored under it)", () => {
  assert.strictEqual(manifest.browser_specific_settings.gecko.id, "basic-auth-remember@local");
});

test("version is dotted numbers, as AMO requires", () => {
  assert.match(manifest.version, /^\d+(\.\d+){1,3}$/);
});

const iconSets = {
  icons: manifest.icons,
  "browser_action.default_icon": manifest.browser_action.default_icon,
};
for (const [where, icons] of Object.entries(iconSets)) {
  test(`${where}: every icon exists at its declared size`, () => {
    assert.ok(icons && Object.keys(icons).length > 0, `no ${where}`);
    for (const [size, rel] of Object.entries(icons)) {
      const { width, height } = pngSize(path.join(extDir, rel));
      assert.deepStrictEqual([width, height], [Number(size), Number(size)], rel);
    }
  });
}

test("listing icon for AMO is 128x128", () => {
  assert.deepStrictEqual(pngSize(path.join(__dirname, "../amo/icon-128.png")), { width: 128, height: 128 });
});

test("AMO screenshots are 1280x800 (npm run screenshots)", () => {
  const dir = path.join(__dirname, "../amo/screenshots");
  const shots = fs.readdirSync(dir).filter((f) => f.endsWith(".png"));
  assert.ok(shots.length >= 3, "expected at least 3 screenshots");
  for (const shot of shots) {
    assert.deepStrictEqual(pngSize(path.join(dir, shot)), { width: 1280, height: 800 }, shot);
  }
});

test("AMO listing metadata is valid and names a license", () => {
  const meta = JSON.parse(fs.readFileSync(path.join(__dirname, "../amo/metadata.json"), "utf8"));
  assert.ok(meta.summary["en-US"].length <= 250, "summary over AMO's 250-character limit");
  assert.ok(meta.version.license);
  assert.ok(meta.categories.firefox.length > 0);
});

test("extension/ (everything that gets packaged) holds no credential files", () => {
  const files = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else files.push(path.relative(extDir, full));
    }
  };
  walk(extDir);
  const suspicious = files.filter((f) => /(^|\/)\.env|\.pem$|\.key$|credential|secret/i.test(f));
  assert.deepStrictEqual(suspicious, []);
});
